  grid-template-columns: repeat(13, 1fr);
  gap: 3px;
}
.week-box {
  aspect-ratio: 1;
  background: #24282d;
  border-radius: 2px;
  transition: background 0.2s;
}
/* 热力图使用全站强调色的透明度阶梯，替代灰色阶梯 */
.intensity-0 { background: #24282d; }
.intensity-1 { background: rgba(102, 177, 255, 0.20); }
.intensity-2 { background: rgba(102, 177, 255, 0.40); }
.intensity-3 { background: rgba(102, 177, 255, 0.65); }
.intensity-4 { background: #8cc5ff; box-shadow: 0 0 5px rgba(140, 197, 255, 0.5); }

@media (prefers-reduced-motion: reduce) {
  .record-item,
  .empty-state { animation: none; }
}

