<template>
  <div class="settings-page">
    <div class="container">
      <h1 class="page-title">设置</h1>
      <p class="page-desc">自定义站点外观，所有修改立即生效并自动保存在本地。</p>

      <!-- 主题色 -->
      <section class="settings-section">
        <h2 class="section-title">主题色</h2>
        <div class="color-row">
          <button
            v-for="color in primaryColorOptions"
            :key="color.value"
            class="color-swatch"
            :class="{ active: isActiveColor(color.value) }"
            :style="{ backgroundColor: color.value }"
            :title="color.name"
            @click="update({ primaryColor: color.value })"
          ></button>
          <label class="color-custom" :class="{ active: isCustomColor }" title="自定义颜色">
            <input
              type="color"
              :value="settings.primaryColor"
              @input="update({ primaryColor: $event.target.value })"
            >
            <span class="color-custom-text">自定义</span>
          </label>
        </div>
      </section>

      <!-- 字体设置 -->
      <section class="settings-section">
        <h2 class="section-title">字体设置</h2>
        <div class="font-group">
          <h3 class="font-group-title">正文字体</h3>
          <div class="font-list">
            <button
              v-for="font in bodyFontOptions"
              :key="font.name"
              class="font-item"
              :class="{ active: settings.bodyFont === font.value }"
              @click="update({ bodyFont: font.value })"
            >
              <span class="font-name">{{ font.name }}</span>
            </button>
          </div>
        </div>
        <div class="font-group">
          <h3 class="font-group-title">标题字体</h3>
          <div class="font-list">
            <button
              v-for="font in titleFontOptions"
              :key="font.name"
              class="font-item"
              :class="{ active: settings.titleFont === font.value }"
              @click="update({ titleFont: font.value })"
            >
              <span class="font-name">{{ font.name }}</span>
            </button>
          </div>
        </div>
      </section>

      <!-- 实时预览 -->
      <section class="settings-section">
        <h2 class="section-title">实时预览</h2>
        <div class="preview-panel">
          <h3 class="preview-title">示例标题 Sample Title</h3>
          <p class="preview-text">
            这是一段正文示例文本，用于预览当前的字体与颜色搭配效果。
            The quick brown fox jumps over the lazy dog. 0123456789
          </p>
          <div class="preview-actions">
            <button class="preview-btn-primary">主题色按钮</button>
            <button class="preview-btn-plain">普通按钮</button>
          </div>
        </div>
      </section>

      <button class="reset-btn" @click="reset">恢复默认设置</button>
    </div>
  </div>
</template>

<script>
import {
  settingsStore,
  updateSettings,
  resetSettings,
  PRIMARY_COLOR_OPTIONS,
  BODY_FONT_OPTIONS,
  TITLE_FONT_OPTIONS
} from '@/constants/theme'

export default {
  name: 'Settings',
  data() {
    return {
      primaryColorOptions: PRIMARY_COLOR_OPTIONS,
      bodyFontOptions: BODY_FONT_OPTIONS,
      titleFontOptions: TITLE_FONT_OPTIONS
    }
  },
  computed: {
    settings() {
      return settingsStore.settings
    },
    isCustomColor() {
      const current = this.settings.primaryColor.toLowerCase()
      return !this.primaryColorOptions.some(c => c.value.toLowerCase() === current)
    }
  },
  methods: {
    update(patch) {
      updateSettings(patch)
    },
    reset() {
      resetSettings()
    },
    isActiveColor(value) {
      return this.settings.primaryColor.toLowerCase() === value.toLowerCase()
    }
  }
}
</script>

